:root {
  --bg:#101611;--panel:#1b251e;--panel2:#222e25;--line:#39483b;--cream:#f1eedf;--muted:#a3b09e;--lime:#d3f36b;--orange:#ff9a5d;--red:#ff6b5d}
* {
  box-sizing:border-box}
body {
  margin:0;min-height:100vh;background:radial-gradient(ellipse at 48% -15%,#33442b 0,transparent 47%),var(--bg);color:var(--cream);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;padding:20px}
.shell {
  max-width:1390px;margin:auto}
.top {
  display:flex;align-items:center;justify-content:space-between;margin:0 2px 16px}
.brand {
  display:flex;gap:12px;align-items:center}
.logo {
  width:44px;height:44px;border:1px solid #536044;border-radius:14px;background:#283327;display:grid;place-items:center;font-size:23px}
.eyebrow,.mono {
  font-family:ui-monospace,monospace;text-transform:uppercase;letter-spacing:.13em}
.eyebrow {
  font-size:10px;color:var(--lime);font-weight:700}
.brand h1 {
  font-size:18px;line-height:1;margin:4px 0 0;letter-spacing:-.04em}
.tag {
  border:1px solid var(--line);border-radius:999px;padding:8px 13px;color:#c7d0c4;font-size:12px}
.tag b {
  color:var(--lime)}
.layout {
  display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:15px;align-items:start}
.card {
  background:linear-gradient(145deg,#202a21,#18211b);border:1px solid #364237;border-radius:17px;overflow:hidden;box-shadow:0 18px 60px #0004}
.gamehead {
  height:58px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #344037}
.mapname {
  display:flex;gap:11px;align-items:center;font-size:13px;font-weight:700}
.live {
  width:8px;height:8px;border-radius:99px;background:#badb56;box-shadow:0 0 12px #bde25a}
.mapname small {
  display:block;color:var(--muted);font-size:10px;font-weight:500;margin-top:3px}
.hud {
  display:flex;gap:7px}
.stat {
  background:#121a14;border:1px solid #344037;border-radius:9px;padding:7px 10px;min-width:69px}
.stat span {
  font-size:9px;color:var(--muted);display:block;text-transform:uppercase;letter-spacing:.08em}
.stat b {
  font:600 14px ui-monospace,monospace;display:block;margin-top:2px}
.stat .heart {
  color:#ff7768}
.stat .coin {
  color:var(--lime)}
.canvasbox {
  position:relative;background:#1a2a1e}
.canvasbox canvas {
  display:block;width:100%;aspect-ratio:1.75;touch-action:none}
.toast {
  position:absolute;left:50%;top:13px;transform:translate(-50%,-12px);padding:9px 14px;background:#101611e8;border:1px solid #607449;border-radius:10px;font-size:12px;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap;z-index:2}
.toast.show {
  opacity:1;transform:translate(-50%,0)}
.gamefoot {
  display:flex;align-items:center;justify-content:space-between;padding:11px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}
.gamefoot strong {
  color:var(--cream)}
button {
  font:inherit;color:inherit;cursor:pointer}
.primary,.secondary {
  border-radius:9px;padding:9px 12px;font-size:11px;font-weight:800;border:1px solid transparent;transition:.15s}
.primary {
  background:var(--lime);color:#182012}
.primary:hover {
  background:#e2ff88;transform:translateY(-1px)}
.secondary {
  background:#29352b;border-color:#485746}
.secondary:hover {
  background:#344334}
.controls {
  display:flex;gap:7px}
