  display:grid;gap:12px}
.panel {
  padding:15px;background:linear-gradient(145deg,#202a21,#19221c);border:1px solid #364237;border-radius:15px}
.panelhead {
  display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.panelhead h2 {
  margin:0;font-size:13px;letter-spacing:-.02em}
.panelhead span {
  font:10px ui-monospace,monospace;color:var(--muted)}
.towerlist {
  display:grid;gap:8px}
.tower {
  width:100%;text-align:left;display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:10px;padding:9px;border-radius:11px;background:#18211b;border:1px solid #344037;transition:.15s}
.tower:hover {
  border-color:#71804e;background:#202d22}
.tower.selected {
  border-color:var(--lime);box-shadow:0 0 0 1px #d3f36b40 inset}
.foodicon {
  width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:#2c3828;font-size:22px}
.tower h3 {
  margin:0;font-size:12px}
.tower p {
  margin:3px 0 0;font-size:10px;color:var(--muted)}
.cost {
  font:11px ui-monospace,monospace;color:var(--lime)}
.tower small {
  display:block;color:#aab8a7;font-size:9px;margin-top:4px}
.hint {
  margin:10px 0 0;color:var(--muted);font-size:10px;line-height:1.5}
.actionrow {
  display:flex;gap:7px}
.actionrow button {
  flex:1}
.selectedbox {
  display:none;margin-top:11px;padding-top:11px;border-top:1px solid #344037}
.selectedbox.active {
  display:block}
.selectedtop {
  display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-size:12px;font-weight:700}
.selectedtop small {
  color:var(--muted);font-size:10px;font-weight:500}
.smallbtn {
  width:100%;padding:8px;background:#2a3926;border:1px solid #516442;border-radius:8px;color:var(--lime);font-size:10px;font-weight:800}
.smallbtn:disabled {
  opacity:.42;cursor:not-allowed}
.smallbtn.sell {
  margin-top:6px;color:#ffad83;background:#352720;border-color:#634331}
.wavecard {
  padding:14px;background:linear-gradient(135deg,#313e27,#202b22);border:1px solid #52633c;border-radius:15px}
.wave-top {
  display:flex;justify-content:space-between;align-items:center}
.wave-top h2 {
  margin:0;font-size:13px}
.wave-num {
  color:var(--lime);font:700 12px ui-monospace,monospace}
.wavecard p {
  margin:6px 0 12px;color:#c1cbb9;font-size:10px}
.wavebtn {
  width:100%;padding:10px}
.progress {
  height:4px;background:#151e17;border-radius:9px;margin-top:11px;overflow:hidden}
.progress i {
  height:100%;display:block;width:0;background:var(--lime);transition:width .2s}
.log {
  font-size:10px;color:var(--muted);line-height:1.8}
.log div {
  display:flex;gap:8px}
.log b {
  color:var(--lime);font-weight:500}
.footnote {
  text-align:center;color:#718071;font-size:10px;margin:12px 0}
.overlay {
  position:absolute;inset:0;background:#0b100de0;display:grid;place-items:center;text-align:center;padding:20px;z-index:3}
.overlay.hidden {
  display:none}
.dialog {
  max-width:340px}
.dialog .big {
  font-size:46px}
.dialog h2 {
  font-size:24px;margin:5px 0}
.dialog p {
  color:#b4c0af;line-height:1.55;font-size:13px}
.dialog button {
  margin-top:8px;padding:11px 21px}
.mobile-tools {
  display:none}
@media(max-width:850px) {
  body {
  padding:12px}
.layout {
  grid-template-columns:1fr}
.side {
  grid-template-columns:1fr 1fr}
.panel {
  padding:12px}
.towerlist {
  grid-template-columns:1fr}
