  display:none}
}
@media(max-width:560px) {
  body {
  padding:8px}
.shell {
  width:100%}
.top {
  margin-bottom:9px}
.brand h1 {
  font-size:15px}
.logo {
  width:38px;height:38px}
.tag {
  font-size:10px;padding:7px 9px}
.layout {
  gap:9px}
.gamehead {
  height:auto;min-height:53px;padding:8px 10px;gap:4px}
.hud {
  gap:4px}
.stat {
  min-width:50px;padding:6px}
.stat span {
  font-size:8px}
.stat b {
  font-size:12px}
.gamefoot {
  padding:9px 10px;font-size:10px}
.side {
  grid-template-columns:1fr}
